<div id="app-content"><div id="app-content-wrapper"><?php print_unescaped($this->inc('_nav'));?><main class="erp-main erp-file-activity-page">
<header class="erp-project-hero"><div><span class="erp-record-kicker">Nextcloud Dateien</span><h1>Dateiaktivitäten</h1><p class="erp-muted">Neue und geänderte Dateien in allen Betrio-Projekten – auch bei Upload über Nextcloud, Desktop-Sync oder WebDAV.</p></div></header>
<section class="erp-card erp-wide"><div class="erp-section-head"><div><h2>Letzte Aktivitäten</h2><p class="erp-muted">Die neuesten Dateiänderungen aus deinen freigegebenen Projekten.</p></div></div>
<?php if($activities):?><div class="erp-file-activity-toolbar" aria-label="Dateiaktivitäten filtern"><button type="button" class="erp-file-activity-filter is-active" data-action="all">Alle</button><button type="button" class="erp-file-activity-filter" data-action="file_created">Neu</button><button type="button" class="erp-file-activity-filter" data-action="file_changed">Geändert</button><button type="button" class="erp-file-activity-filter" data-action="file_moved">Verschoben</button><button type="button" class="erp-file-activity-filter" data-action="file_deleted">Gelöscht</button></div><?php endif;?>
