<?php foreach($activities as $a):?><a class="erp-file-activity-row" data-action="<?php p((string)($a['action']??''));?>" href="<?php p($url->linkToRoute('reinhardterp.page.projectExplorer',['id'=>(int)$a['project_id']]));?>"><span class="erp-file-activity-badge"><?php p($labels[$a['action']]??'Datei');?></span><span><strong><?php p(($a['project_no']??'').' · '.($a['project_title']??''));?></strong><small><?php p((string)($a['details']??''));?></small></span><span class="erp-file-activity-meta"><?php p((string)($a['display_name']??$a['created_by']??''));?><br><?php p(date('d.m.Y H:i',strtotime((string)$a['created_at'])));?></span></a><?php endforeach;?></div><div class="erp-file-activity-empty-filter" hidden>Keine Aktivitäten für diesen Filter vorhanden.</div><?php endif;?></section><script>(function(){const buttons=[...document.querySelectorAll('.erp-file-activity-filter')],rows=[...document.querySelectorAll('.erp-file-activity-row')],empty=document.querySelector('.erp-file-activity-empty-filter');buttons.forEach(b=>b.addEventListener('click',()=>{buttons.forEach(x=>x.classList.remove('is-active'));b.classList.add('is-active');const action=b.dataset.action;let visible=0;rows.forEach(r=>{const show=action==='all'||r.dataset.action===action;r.hidden=!show;if(show)visible++;});if(empty)empty.hidden=visible!==0;}));})();</script></main></div></div>
